    /* ---------------------------------------------------------------------------------- */
    /* Account edge cases                                                                  */
    /* ---------------------------------------------------------------------------------- */

    @isTest
    static void testInsertWonWithoutAccountCreatesOnlyTask() {
        Opportunity opp = newOpp('no-account', null, WON, BASE_CLOSE);

        Test.startTest();
        insert opp;
        Integer queries = Limits.getQueries();
