                               FROM Opportunity
                              WHERE Id = :opp.Id];
        assertExact(HANDOVER, saved.NextStep, 'NextStep when the opportunity has no account');
        Assert.isNull(saved.AccountId, 'Sanity: this opportunity really has no account');

