/**
 * Runtime utility for reading the active values of any picklist or
 * multi-select picklist field in the org.
 *
 * Usage:
 *   List<PicklistService.Option> options =
 *       PicklistService.activeOptions('FB_Asset_Check__c', 'Status__c');
 *
 * Guarantees:
 *  - Object / field API names are matched case-insensitively.
 *  - Only active entries are returned, in field definition order.
 *  - Every failure mode throws PicklistService.PicklistServiceException
 *    (never a NullPointerException or an unhandled platform exception).
 */
public with sharing class PicklistService {

    /* ------------------------------------------------------------------ *
     *  Inner classes
     * ------------------------------------------------------------------ */

    /** A single picklist entry: the API value, its label, and whether it
     *  is the field's default value. */
    public class Option {
        /** API value of the entry (e.g. "In_Progress"). */
        public String value;
        /** Translated/defined label of the entry (e.g. "In Progress"). */
        public String label;
        /** True only for the field's default value. */
        public Boolean isDefault;

        public Option() {
            this.value = null;
            this.label = null;
            this.isDefault = false;
        }

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = (isDefault == true);
        }
    }

    /** Custom exception thrown by this service for every failure mode. */
    public class PicklistServiceException extends Exception {
    }

    /* ------------------------------------------------------------------ *
     *  Caches (describe results are stable within a transaction)
     * ------------------------------------------------------------------ */

    private static Map<String, Schema.SObjectType> objectTypeCache =
        new Map<String, Schema.SObjectType>();
    private static Map<String, Schema.DescribeFieldResult> fieldDescribeCache =
        new Map<String, Schema.DescribeFieldResult>();

    /* ------------------------------------------------------------------ *
     *  Public API
     * ------------------------------------------------------------------ */

    /**
     * Returns the active values of a picklist or multi-select picklist
     * field, in the order they are defined on the field.
     *
     * @param objectApiName API name of the sObject (standard or custom, any case).
     * @param fieldApiName  API name of the picklist field (any case).
     * @return active entries; never null.
     * @throws PicklistServiceException if a name is null/blank, the object
     *         does not exist, the field does not exist on the object, or the
     *         field is not a picklist / multi-select picklist.
     */
    public static List<PicklistService.Option> activeOptions(
        String objectApiName,
        String fieldApiName
    ) {
        // --- Guard 1: names must be present -------------------------------
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException(
                'Object API name must not be null or blank.'
            );
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException(
                'Field API name must not be null or blank.'
            );
        }

        String objectName = objectApiName.trim();
        String fieldName = fieldApiName.trim();

        // --- Guard 2: object must exist -----------------------------------
        Schema.SObjectType sObjectType = resolveObjectType(objectName);
        if (sObjectType == null) {
            throw new PicklistServiceException(
                'Unknown sObject: ' + objectName
            );
        }

        // --- Guard 3: field must exist on the object ----------------------
        Schema.DescribeFieldResult fieldDescribe =
            resolveFieldDescribe(sObjectType, objectName, fieldName);
        if (fieldDescribe == null) {
            throw new PicklistServiceException(
                'Field ' + fieldName + ' does not exist on ' + objectName
            );
        }

        // --- Guard 4: must be a picklist (or multi-select picklist) -------
        Schema.DisplayType fieldType = fieldDescribe.getType();
        if (fieldType != Schema.DisplayType.Picklist &&
            fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'Field ' + fieldName + ' on ' + objectName +
                ' is not a picklist or multi-select picklist (type: ' +
                String.valueOf(fieldType) + ').'
            );
        }

        // --- Build the result: active entries, definition order -----------
        List<PicklistService.Option> options = new List<PicklistService.Option>();
        try {
            for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
                if (entry == null || !entry.isActive()) {
                    continue; // inactive values are left out
                }
                options.add(
                    new Option(
                        entry.getValue(),
                        entry.getLabel(),
                        entry.isDefaultValue()
                    )
                );
            }
        } catch (PicklistServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new PicklistServiceException(
                'Unable to read picklist values for ' + objectName + '.' +
                fieldName + ': ' + e.getMessage()
            );
        }
        return options;
    }

    /* ------------------------------------------------------------------ *
     *  Private helpers
     * ------------------------------------------------------------------ */

    /** Case-insensitive lookup of an sObject type; null when it does not exist. */
    @TestVisible
    private static Schema.SObjectType resolveObjectType(String objectApiName) {
        try {
            String key = objectApiName.toLowerCase();

            if (objectTypeCache.containsKey(key)) {
                return objectTypeCache.get(key);
            }

            Map<String, Schema.SObjectType> globalDescribe =
                Schema.getGlobalDescribe();

            Schema.SObjectType found = globalDescribe.get(objectApiName);
            if (found == null) {
                for (String apiName : globalDescribe.keySet()) {
                    if (apiName != null && apiName.equalsIgnoreCase(objectApiName)) {
                        found = globalDescribe.get(apiName);
                        break;
                    }
                }
            }
            objectTypeCache.put(key, found);
            return found;
        } catch (Exception e) {
            throw new PicklistServiceException(
                'Unable to resolve sObject "' + objectApiName + '": ' + e.getMessage()
            );
        }
    }

    /** Case-insensitive lookup of a field describe; null when it does not exist. */
    @TestVisible
    private static Schema.DescribeFieldResult resolveFieldDescribe(
        Schema.SObjectType sObjectType,
        String objectApiName,
        String fieldApiName
    ) {
        try {
            String cacheKey =
                objectApiName.toLowerCase() + '.' + fieldApiName.toLowerCase();
            if (fieldDescribeCache.containsKey(cacheKey)) {
                return fieldDescribeCache.get(cacheKey);
            }

            Map<String, Schema.SObjectField> fieldMap =
                sObjectType.getDescribe().fields.getMap();

            Schema.SObjectField field = fieldMap.get(fieldApiName);
            if (field == null) {
                for (String apiName : fieldMap.keySet()) {
                    if (apiName != null && apiName.equalsIgnoreCase(fieldApiName)) {
                        field = fieldMap.get(apiName);
                        break;
                    }
                }
            }

            Schema.DescribeFieldResult describe =
                (field == null) ? null : field.getDescribe();

            fieldDescribeCache.put(cacheKey, describe);
            return describe;
        } catch (PicklistServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new PicklistServiceException(
                'Unable to resolve field "' + fieldApiName + '" on "' +
                objectApiName + '": ' + e.getMessage()
            );
        }
    }
}
