public inherited sharing class OpportunitiesSelector extends fflib_SObjectSelector {
    public Schema.SObjectType getSObjectType() {
        return Opportunity.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Opportunity.Id,
            Opportunity.Name,
            Opportunity.AccountId,
            Opportunity.StageName,
            Opportunity.Amount,
            Opportunity.CloseDate
        };
    }

    public List<Opportunity> selectById(Set<Id> opportunityIds) {
        return (List<Opportunity>) selectSObjectsById(opportunityIds);
    }

    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        List<Opportunity> opportunities = new List<Opportunity>();

        if (accountIds == null || accountIds.isEmpty()) {
            return opportunities;
        }
        if (maxRecords == null || maxRecords < 1) {
            return opportunities;
        }

        // Build from the selector's query factory so the standard field list,
        // the selector's security settings and any default ordering keep applying.
        fflib_QueryFactory queryFactory = newQueryFactory();

        // Add the parent account's name to each row.
        queryFactory.selectField('Account.Name');

        // Open opportunities of the requested accounts only (bind variable, bulk safe).
        queryFactory.setCondition('IsClosed = false AND AccountId IN :accountIds');

        // At most maxRecords rows, still a single query.
        queryFactory.setLimit(maxRecords);

        String soql = queryFactory.toSoql();

        // Replace any ordering produced by the factory (e.g. the default ordering
        // by Name) with the ordering required by this method:
        //   1. Amount descending, opportunities without an Amount last
        //   2. CloseDate ascending for equal amounts
        final String orderClause = ' ORDER BY Amount DESC NULLS LAST, CloseDate ASC';
        Integer orderIdx = soql.indexOf(' ORDER BY ');
        Integer limitIdx = soql.indexOf(' LIMIT ');
        if (orderIdx < 0) {
            // No ordering present: insert in front of LIMIT (or at the end).
            orderIdx = (limitIdx >= 0) ? limitIdx : soql.length();
        }
        // Keep everything from LIMIT onwards (the LIMIT clause must stay last).
        Integer endIdx = (limitIdx >= orderIdx) ? limitIdx : soql.length();
        soql = soql.substring(0, orderIdx) + orderClause + soql.substring(endIdx);

        opportunities = (List<Opportunity>) Database.query(soql);
        return opportunities;
    }
}
