/**
 * Service responsible for creating Accounts together with their initial
 * Contacts, persisting everything through a single fflib Unit of Work
 * (Apex Enterprise Patterns / fflib-apex-common).
 *
 * All records are registered with one fflib_SObjectUnitOfWork and written by
 * a single commitWork(), so the whole operation is bulk-safe and issues only
 * the DML performed by the unit of work itself.
 */
public with sharing class AccountOnboardingService
{
	/**
	 * Creates one Account per map key and, for each last name in the key's
	 * value list, one Contact related to that Account.
	 *
	 * @param contactLastNamesByAccountName Map of Account name -> list of Contact last names.
	 * @return The newly created Accounts, with their Ids populated.
	 */
	public static List<Account> createAccountsWithContacts(
		Map<String, List<String>> contactLastNamesByAccountName)
	{
		List<Account> createdAccounts = new List<Account>();

		// A null or empty request writes nothing at all.
		if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty())
		{
			return createdAccounts;
		}

		// Capture the schema tokens up front, before any local variable is
		// declared whose name could shadow a standard object type name
		// (Apex identifiers are case-insensitive: a local "contact" variable
		// would turn "Contact.AccountId" into an instance access returning Id
		// instead of a Schema.SObjectField token).
		List<Schema.SObjectType> sObjectTypes = new List<Schema.SObjectType>
		{
			Account.SObjectType,
			Contact.SObjectType
		};
		Schema.SObjectField accountLookupField = Contact.AccountId;

		// A single unit of work for the whole operation; Accounts are listed
		// first so they are inserted before the Contacts that reference them.
		fflib_SObjectUnitOfWork unitOfWork = new fflib_SObjectUnitOfWork(sObjectTypes);

		for (String accountName : contactLastNamesByAccountName.keySet())
		{
			// Account.Name is mandatory; skip a key that could not be inserted.
			if (String.isBlank(accountName))
			{
				continue;
			}

			Account newAccount = new Account(Name = accountName);
			unitOfWork.registerNew(newAccount);
			createdAccounts.add(newAccount);

			List<String> lastNames = contactLastNamesByAccountName.get(accountName);
			if (lastNames == null || lastNames.isEmpty())
			{
				// The Account is still created; it simply has no Contacts.
				continue;
			}

			for (String lastName : lastNames)
			{
				// Contact.LastName is mandatory; skip values that could not be inserted.
				if (String.isBlank(lastName))
				{
					continue;
				}

				Contact newContact = new Contact(LastName = lastName);
				// Wire the lookup before insert; the unit of work replaces the
				// reference with the generated Account Id when it inserts.
				unitOfWork.registerRelationship(newContact, accountLookupField, newAccount);
				unitOfWork.registerNew(newContact);
			}
		}

		// Single ordered DML pass (Accounts, then Contacts) for the transaction.
		unitOfWork.commitWork();

		return createdAccounts;
	}
}
