/**
 * Keeps Account.Rating in sync with the account's open opportunity pipeline.
 *
 * Fires after insert, and after an update in which StageName or Amount changed -
 * those are the only fields that can move the parent account between
 * Cold / Warm / Hot.
 *
 * IMPORTANT: instead of one @future call per opportunity (which exhausts the
 * asynchronous-call limit on a CPQ batch of 200), the affected AccountIds are
 * collected first and handed to AccountRatingService in a SINGLE @future call per
 * trigger transaction. The result is identical - one recalculation per distinct
 * account - but it costs one async call instead of up to 200.
 */
trigger OpportunityTrigger on Opportunity (after insert, after update) {

    Set<Id> accountIds = new Set<Id>();

    for (Opportunity opp : Trigger.new) {

        if (Trigger.isInsert) {
            // A brand-new opportunity always adds open pipeline to its account.
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
            continue;
        }

        // --- update ---
        Opportunity oldOpp = Trigger.oldMap.get(opp.Id);

        // StageName decides "open vs closed", Amount decides ">= 100k".
        Boolean pipelineChanged = oldOpp.StageName != opp.StageName
                                || oldOpp.Amount      != opp.Amount;
        // Re-parenting changes both accounts' pipeline even if Stage/Amount are untouched.
        Boolean accountChanged  = oldOpp.AccountId != opp.AccountId;

        if (!pipelineChanged && !accountChanged) {
            // Nothing that can change any rating: skip the async call entirely.
            continue;
        }

        if (opp.AccountId != null) {
            accountIds.add(opp.AccountId);              // current parent
        }
        if (accountChanged && oldOpp.AccountId != null) {
            accountIds.add(oldOpp.AccountId);           // previous parent lost pipeline
        }
    }

    if (!accountIds.isEmpty()) {
        // One future call for the whole batch of up to 200 opportunities.
        AccountRatingService.recalculateAll(accountIds);
    }
}
