/**
 * Case (after update) - schedules the customer feedback survey.
 *
 * The trigger only works out WHICH cases just closed; all survey work happens
 * asynchronously in CaseSurveyJob, one Case per job, so a failure on one Case
 * can never stop the others. There is no SOQL and no DML in here, which keeps
 * the trigger cheap and bulk safe for list-view mass edits and for the nightly
 * API job that closes up to 200 Cases in a single transaction.
 */
trigger CaseTrigger on Case (after update) {
    for (Case updatedCase : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(updatedCase.Id);

        // Only the not-closed -> closed transition (compared against Trigger.old).
        if (oldCase == null || !updatedCase.IsClosed || oldCase.IsClosed) {
            continue;
        }

        // At most one survey per Case per transaction, in case this trigger runs
        // again for the same Case later in the same transaction.
        if (!CaseSurveyJob.markScheduled(updatedCase.Id)) {
            continue;
        }

        // One job per Case: each case is handled on its own, so one failure
        // cannot affect the others.
        System.enqueueJob(new CaseSurveyJob(updatedCase.Id));
    }
}
