```javascript
import { LightningElement, api, wire } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';

import NAME_FIELD from '@salesforce/schema/Account.Name';
import INDUSTRY_FIELD from '@salesforce/schema/Account.Industry';
import ANNUAL_REVENUE_FIELD from '@salesforce/schema/Account.AnnualRevenue';
import OWNER_NAME_FIELD from '@salesforce/schema/Account.Owner.Name';

// The four fields the record page header needs.
const ACCOUNT_FIELDS = [
    NAME_FIELD,
    INDUSTRY_FIELD,
    ANNUAL_REVENUE_FIELD,
    OWNER_NAME_FIELD
];

export default class AccountHeader extends LightningElement {
    /**
     * Public property supplied by the record page (or a reused console tab).
     * It is reactive: when recordId changes, the getRecord wire re-executes
     * and the component automatically reloads the new Account.
     */
    @api recordId;

    record;
    error;

    @wire(getRecord, {
        recordId: '$recordId',
        fields: ACCOUNT_FIELDS
    })
    wiredAccount({ data, error }) {
        if (data) {
            this.record = data;
            this.error = undefined;
        } else if (error) {
            this.error = error;
            this.record = undefined;
        }
    }

    // ---- State helpers --------------------------------------------------

    // Still loading: neither data nor error has come back yet.
    get isLoading() {
        return !this.record && !this.error;
    }

    get hasRecord() {
        return !!this.record;
    }

    get hasError() {
        return !!this.error;
    }

    get errorMessage() {
        if (this.error && this.error.body && this.error.body.message) {
            return this.error.body.message;
        }
        return '';
    }

    // ---- Field accessors ------------------------------------------------

    get name() {
        return this.readField([
            'Account.Name',
            'Name',
            NAME_FIELD
        ]);
    }

    get industry() {
        return this.readField([
            'Account.Industry',
            'Industry',
            INDUSTRY_FIELD
        ]);
    }

    get hasIndustry() {
        const value = this.industry;
        return value !== undefined && value !== null && value !== '';
    }

    get revenue() {
        return this.readField([
            'Account.AnnualRevenue',
            'AnnualRevenue',
            ANNUAL_REVENUE_FIELD
        ]);
    }

    get ownerName() {
        return this.readField([
            'Account.Owner.Name',
            'Owner.Name',
            'Owner',
            OWNER_NAME_FIELD
        ]);
    }

    /**
     * Reads a field value from the wired record, accepting the different key
     * shapes Lightning Data Service may expose (fully qualified
     * "Account.Owner.Name", unqualified "Name", or whatever the
     * `@salesforce/schema` import resolves to). Falls back to the record's
     * own top-level properties so a partially shaped record still renders.
     *
     * Returns undefined when the record has not loaded or the field has no
     * value, so the template guards behave predictably.
     */
    readField(candidateKeys) {
        const record = this.record;
        if (!record) {
            return undefined;
        }

        const sources = [record.fields, record];

        for (const source of sources) {
            if (!source) {
                continue;
            }
            for (const key of candidateKeys) {
                if (key === undefined || key === null || key === '') {
                    continue;
                }
                const field = source[key];
                if (field === undefined || field === null) {
                    continue;
                }
                if (typeof field === 'object') {
                    if (field.value !== undefined && field.value !== null) {
                        return field.value;
                    }
                    if (
                        field.displayValue !== undefined &&
                        field.displayValue !== null
                    ) {
                        return field.displayValue;
                    }
                } else {
                    return field;
                }
            }
        }

        return undefined;
    }
}
