import { LightningElement, api } from 'lwc';
import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

export default class OpenOpportunities extends LightningElement {
    /** The Account record Id (provided by the record page). */
    @api recordId;

    /** Opportunities returned by Apex. */
    opportunities = [];

    /** Any error thrown by the Apex call. */
    error;

    /** True while an Apex call is in flight. */
    isLoading = false;

    /**
     * Guard so the imperative call happens exactly once on insertion,
     * even if connectedCallback fires more than once (e.g. on re-insert).
     */
    hasLoadedOnce = false;

    connectedCallback() {
        if (this.hasLoadedOnce) {
            return;
        }
        this.hasLoadedOnce = true;
        this.loadOpportunities();
    }

    /**
     * Imperative (non-@wire) call to Apex.
     * Used both for the initial load and for the Retry button.
     */
    loadOpportunities() {
        this.isLoading = true;
        this.error = undefined;
        this.opportunities = [];

        getOpenOpportunities({ accountId: this.recordId })
            .then((result) => {
                this.opportunities = Array.isArray(result) ? result : [];
                this.error = undefined;
            })
            .catch((err) => {
                this.error = err;
                this.opportunities = [];
            })
            .finally(() => {
                this.isLoading = false;
            });
    }

    /** Retry button handler: re-runs the same Apex method (spinner shown while running). */
    handleRetry() {
        this.loadOpportunities();
    }

    get hasError() {
        return this.error !== undefined && this.error !== null;
    }

    get errorMessage() {
        if (this.error && this.error.body && this.error.body.message) {
            return this.error.body.message;
        }
        return this.error && this.error.message
            ? this.error.message
            : 'An unexpected error occurred.';
    }

    get hasOpportunities() {
        return !this.isLoading && !this.hasError && this.opportunities.length > 0;
    }

    get isEmpty() {
        return !this.isLoading && !this.hasError && this.opportunities.length === 0;
    }
}
