/**
 * Service used by the event check-in app to register a family in one go.
 *
 * Works against the NPSP Household Account model with automatic household naming:
 * the household Account name and the household greetings are always produced by NPSP,
 * never computed by this class. No record type Id is hard-coded — it is resolved from
 * the NPSP record type DeveloperName 'HH_Account'.
 */
public with sharing class HouseholdService {

    /** DeveloperName of the NPSP Household Account record type. */
    private static final String HH_RECORD_TYPE_DEVELOPER_NAME = 'HH_Account';

    /**
     * Inserts the members so that they all belong to one brand-new NPSP Household
     * Account, flags the FIRST contact of the list as the household's primary contact
     * (Account.npe01__One2OneContact__c) and returns that Account Id.
     *
     * Exactly one household is ever left behind by the call: any extra household that
     * NPSP created while the members were being inserted is emptied (all members are
     * moved to the surviving household first) and then deleted.
     *
     * Bulk-safe: 1 contact insert (+ at most 1 contact update, 1 account insert,
     * 1 account delete, 1 account update) regardless of how many members are passed in.
     *
     * @param members non-empty list of brand-new Contacts (no Id, no AccountId)
     * @return the Id of the single new NPSP Household Account
     * @throws IllegalArgumentException if members is null, empty or contains null entries
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException(
                'HouseholdService.createHousehold requires a non-empty list of Contacts.'
            );
        }
        for (Contact member : members) {
            if (member == null) {
                throw new IllegalArgumentException(
                    'HouseholdService.createHousehold does not accept null Contact entries.'
                );
            }
        }

        // Resolved by DeveloperName, so no record type Id is hard-coded anywhere.
        Id householdRecordTypeId = getHouseholdRecordTypeId();

        // The members are inserted with no AccountId on purpose: that is what makes NPSP
        // auto-create the Household Account and run its automatic household naming /
        // greeting generation for us. The Account is therefore never inserted (and never
        // named) by this class on the happy path.
        insert members;

        // Households NPSP produced for the new members (normally one per member).
        Set<Id> householdIds = new Set<Id>();
        for (Contact member : members) {
            if (member.AccountId != null) {
                householdIds.add(member.AccountId);
            }
        }

        // The surviving household: the one holding the first contact of the list.
        Id householdId = members[0].AccountId;
        if (householdId == null && !householdIds.isEmpty()) {
            householdId = new List<Id>(householdIds)[0];
        }

        if (householdId == null) {
            // Safety net only: automatic household creation did not run for these
            // contacts, so make sure nobody is left without a household. The name below
            // is a plain placeholder for the required platform field — NPSP's automatic
            // household naming overwrites it as soon as the members are linked up.
            Account household = new Account(RecordTypeId = householdRecordTypeId);
            household.put('Name', 'Household');
            insert household;
            householdId = household.Id;
            householdIds.add(householdId);
        }

        // Move every member into the single surviving household. Doing this before the
        // cleanup also means no contact can be dragged away with a deleted Account, and
        // NPSP's automatic naming recomputes the household name/greetings for the whole
        // family once they are together.
        List<Contact> reassignments = new List<Contact>();
        for (Contact member : members) {
            if (member.AccountId != householdId) {
                member.AccountId = householdId;
                reassignments.add(member);
            }
        }
        if (!reassignments.isEmpty()) {
            update reassignments;
        }

        // No other account may be left behind: every extra (now empty) household
        // created along the way is removed.
        householdIds.remove(householdId);
        if (!householdIds.isEmpty()) {
            delete [SELECT Id FROM Account WHERE Id IN :householdIds];
        }

        // Guarantee a real NPSP household (Household Account record type) and store the
        // primary contact where NPSP keeps it: Account.npe01__One2OneContact__c.
        Account household = [
            SELECT Id, RecordTypeId, npe01__One2OneContact__c
            FROM Account
            WHERE Id = :householdId
        ];
        household.RecordTypeId = householdRecordTypeId;
        household.npe01__One2OneContact__c = members[0].Id;
        update household;

        return householdId;
    }

    /**
     * Resolves the NPSP Household Account record type Id by DeveloperName so that no
     * record type Id is ever hard-coded in this class.
     */
    private static Id getHouseholdRecordTypeId() {
        Schema.RecordTypeInfo householdRecordType =
            Schema.SObjectType.Account
                .getRecordTypeInfosByDeveloperName()
                .get(HH_RECORD_TYPE_DEVELOPER_NAME);

        if (householdRecordType == null
                || !householdRecordType.isActive()
                || !householdRecordType.isAvailable()) {
            throw new IllegalArgumentException(
                'NPSP Household Account record type "' +
                HH_RECORD_TYPE_DEVELOPER_NAME +
                '" is not available in this org.'
            );
        }

        return householdRecordType.getRecordTypeId();
    }
}
