/**
 * NPSP Table-Driven Trigger Management (TDTM) handler that creates a follow-up
 * Task for major gifts.
 *
 * Register with an NPSP Trigger Handler record (NPSP Settings > Trigger Configuration):
 *   Class Name           : OPP_MajorGiftFollowUp_TDTM
 *   SObject (Object)     : Opportunity
 *   Trigger Action       : AfterInsert;AfterUpdate
 *   Load Order           : 5
 *   Run Asynchronous     : unchecked
 *
 * Behaviour:
 *  - AfterInsert : creates one Task when the Opportunity is inserted Closed Won
 *                  with Amount >= 5,000.
 *  - AfterUpdate : creates one Task only when the Opportunity *newly* becomes
 *                  Closed Won with Amount >= 5,000 (it did not satisfy both
 *                  conditions before), so editing an already-qualified gift
 *                  never creates a duplicate Task.
 *
 * Task fields:
 *   Subject      = 'Major gift thank-you call'
 *   Priority     = 'High'
 *   Status       = 'Not Started'
 *   WhatId       = the opportunity
 *   WhoId        = opportunity.npsp__Primary_Contact__c (may be null)
 *   OwnerId      = the opportunity owner
 *   ActivityDate = opportunity.CloseDate + 3 days
 *
 * Bulk-safe: 0 SOQL queries and exactly 1 DML statement, regardless of how many
 * opportunities are processed (up to 200 per transaction).
 * No Apex trigger is defined - NPSP's TDTM dispatcher invokes this class, and
 * deactivating the Trigger Handler record stops it from running.
 */
public with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    /** Minimum amount for a gift to be considered a major gift. */
    @TestVisible
    private static final Decimal MAJOR_GIFT_AMOUNT = 5000;

    /** Days after CloseDate when the follow-up call is due. */
    @TestVisible
    private static final Integer FOLLOW_UP_DAYS = 3;

    /** Subject of the generated Task. */
    @TestVisible
    private static final String TASK_SUBJECT = 'Major gift thank-you call';

    /**
     * TDTM entry point. Called by NPSP's dispatcher for the Trigger Actions
     * configured on the Trigger Handler record (AfterInsert / AfterUpdate).
     */
    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper wrapper = new npsp.TDTM_Runnable.DmlWrapper();
        wrapper.objectsToInsert = new List<SObject>();

        // Nothing to do for actions this handler is not registered for, or with no rows.
        Boolean isAfterInsert = (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert);
        Boolean isAfterUpdate = (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate);

        if ((!isAfterInsert && !isAfterUpdate)
            || newlist == null
            || newlist.isEmpty()) {
            return wrapper;
        }

        List<Opportunity> newOpps = (List<Opportunity>) newlist;
        List<Opportunity> oldOpps = (oldlist != null) ? (List<Opportunity>) oldlist : null;

        List<Task> tasksToInsert = new List<Task>();

        for (Integer i = 0; i < newOpps.size(); i++) {
            Opportunity newOpp = newOpps[i];
            if (newOpp == null) {
                continue;
            }

            // The opportunity must qualify right now: Closed Won and Amount >= 5,000.
            if (!isQualified(newOpp)) {
                continue;
            }

            // On update, skip records that already qualified before the change, so
            // editing an existing major gift never creates a second Task.
            if (isAfterUpdate
                && oldOpps != null
                && i < oldOpps.size()
                && oldOpps[i] != null
                && isQualified(oldOpps[i])) {
                continue;
            }

            tasksToInsert.add(buildTask(newOpp));
        }

        // Single, fully bulkified DML statement (0 SOQL queries).
        if (!tasksToInsert.isEmpty()) {
            Database.insert(tasksToInsert, false);
        }

        // The records were persisted by this handler, so nothing is handed back
        // to the dispatcher for a second insert.
        return wrapper;
    }

    /**
     * An opportunity qualifies when it is Closed Won and its Amount is at least
     * 5,000. A null Amount never qualifies.
     *
     * Note: IsWon is a formula field and is not evaluated in trigger context, so
     * StageName is used as the authoritative check, with IsWon as a fallback for
     * records that were queried.
     */
    @TestVisible
    private static Boolean isQualified(Opportunity opp) {
        if (opp == null || opp.Amount == null || opp.Amount < MAJOR_GIFT_AMOUNT) {
            return false;
        }
        Boolean closedWon = (opp.StageName == 'Closed Won') || (opp.IsWon == true);
        return closedWon;
    }

    /**
     * Builds the follow-up Task for a qualifying opportunity.
     */
    @TestVisible
    private static Task buildTask(Opportunity opp) {
        Task t = new Task();
        t.Subject = TASK_SUBJECT;
        t.Priority = 'High';
        t.Status = 'Not Started';
        t.WhatId = opp.Id;
        // May be null when the opportunity has no primary contact.
        t.WhoId = opp.npsp__Primary_Contact__c;
        t.OwnerId = opp.OwnerId;
        t.ActivityDate = (opp.CloseDate != null)
            ? opp.CloseDate.addDays(FOLLOW_UP_DAYS)
            : Date.today();
        return t;
    }
}
